import{_ as t,c as a,b as s,a0 as o}from"./chunks/framework.DZ_FiXNr.js";const r="/images/knowledge_check.webp",w=JSON.parse(`{"title":"Knowledge Check","description":"Knowledge Check shows you what the major AI assistants believe about your show — and flags anything they get wrong. As more listeners ask ChatGPT, Claude, Perplexity, and Gemini for podcast recommendations, it matters not only that AI mentions you, but that it describes you accurately. Knowledge Check asks each assistant directly, compares its answer against your own show notes and feed, and brings back a clear list of fixes for whatever doesn't add up.","frontmatter":{},"headers":[],"relativePath":"features/knowledge-check.md","filePath":"features/knowledge-check.md"}`),n={name:"features/knowledge-check.md"};function i(h,e,l,c,d,u){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="knowledge-check" tabindex="-1">Knowledge Check <a class="header-anchor" href="#knowledge-check" aria-label="Permalink to &quot;Knowledge Check&quot;">​</a></h1><h2 id="see-what-ai-assistants-actually-know-about-your-podcast" tabindex="-1">See What AI Assistants Actually Know About Your Podcast <a class="header-anchor" href="#see-what-ai-assistants-actually-know-about-your-podcast" aria-label="Permalink to &quot;See What AI Assistants Actually Know About Your Podcast&quot;">​</a></h2><p>Knowledge Check shows you what the major AI assistants believe about your show — and flags anything they get wrong. As more listeners ask ChatGPT, Claude, Perplexity, and Gemini for podcast recommendations, it matters not only that AI mentions you, but that it describes you accurately. Knowledge Check asks each assistant directly, compares its answer against your own show notes and feed, and brings back a clear list of fixes for whatever doesn&#39;t add up.</p><p><a href="/images/knowledge_check.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Knowledge Check Dashboard" width="600px" style="display:block;margin:0 auto;"></a></p><p><strong>To access</strong>: Click <strong>AI Visibility</strong> in the sidebar, then open the <strong>Knowledge Check</strong> tab.</p><h2 id="why-knowledge-accuracy-matters" tabindex="-1"><strong>Why Knowledge Accuracy Matters</strong> <a class="header-anchor" href="#why-knowledge-accuracy-matters" aria-label="Permalink to &quot;**Why Knowledge Accuracy Matters**&quot;">​</a></h2><p>Being recommended by AI is only valuable if the AI gets the details right. When a listener asks an assistant about your show, a confident but wrong answer — the wrong host name, an outdated topic, a made-up detail, or a confusion with a similarly named podcast — can send that listener elsewhere or set the wrong expectation before they ever press play.</p><p>Knowledge Check helps you find and close those gaps. Instead of guessing what AI assistants think, you get a side-by-side look at what each one actually says about your podcast, measured against the facts in your own materials.</p><h2 id="how-to-use-knowledge-check" tabindex="-1"><strong>How to Use Knowledge Check</strong> <a class="header-anchor" href="#how-to-use-knowledge-check" aria-label="Permalink to &quot;**How to Use Knowledge Check**&quot;">​</a></h2><h3 id="run-a-check" tabindex="-1"><strong>Run a Check</strong> <a class="header-anchor" href="#run-a-check" aria-label="Permalink to &quot;**Run a Check**&quot;">​</a></h3><p>Open the Knowledge Check tab and select <strong>Run a knowledge check</strong>. PodSEO asks the same plain-English question about your show to all four major AI assistants:</p><ul><li><strong>ChatGPT</strong> (OpenAI)</li><li><strong>Claude</strong> (Anthropic)</li><li><strong>Perplexity</strong></li><li><strong>Gemini</strong> (Google)</li></ul><p>Where supported, the check compares answers based on an assistant’s existing knowledge with answers using web search. Perplexity is checked with web search. Results may be partial if an assistant does not respond.</p><h3 id="review-your-results" tabindex="-1"><strong>Review Your Results</strong> <a class="header-anchor" href="#review-your-results" aria-label="Permalink to &quot;**Review Your Results**&quot;">​</a></h3><p>When the check finishes, you&#39;ll see a summary headline telling you how many of the four assistants recognize your podcast, along with how many details disagree with your own materials.</p><p>A <strong>Your materials say</strong> reference panel sits at the top, showing what your show notes and feed actually state about your hosts, format, audience, topics, and description. This is the standard every assistant&#39;s answer is measured against, so you can see exactly where any mismatch comes from.</p><p>Below that, each assistant gets its own card showing:</p><ul><li><strong>What it knows</strong> — the hosts, topics, audience, and description it associates with your show</li><li><strong>Trained vs. Web search</strong> — where both are available, compare the answers to identify differences worth investigating</li><li><strong>Mismatch flags</strong> — clear labels when an answer disagrees with your materials, such as hosts that don&#39;t match, topics that drift, an outdated description, or a made-up detail</li><li><strong>Sources</strong> — where the assistant pulled web information from, when available</li><li><strong>A verify link</strong> — open the assistant yourself to confirm what it says</li></ul><h3 id="act-on-recommended-fixes" tabindex="-1"><strong>Act on Recommended Fixes</strong> <a class="header-anchor" href="#act-on-recommended-fixes" aria-label="Permalink to &quot;**Act on Recommended Fixes**&quot;">​</a></h3><p>Knowledge Check ends with a <strong>Recommended next steps</strong> list. Each fix targets a specific gap and explains where to make the change, with links where available. You may need to edit your podcast host, directory listing or website. PodSEO does not directly edit your live feed or website.</p><p>A <strong>website signals</strong> strip also shows whether your site offers the kinds of structured information that help assistants describe you accurately, so you know whether strengthening your web presence could improve future answers.</p><h2 id="when-changes-appear" tabindex="-1"><strong>When changes appear</strong> <a class="header-anchor" href="#when-changes-appear" aria-label="Permalink to &quot;**When changes appear**&quot;">​</a></h2><p>An assistant may not reflect a correction immediately. Timing varies with the assistant, its search mode and the sources it can access; there is no guaranteed update schedule. Check that the correction is published in the right place, then run another check later.</p><h2 id="best-practices" tabindex="-1"><strong>Best Practices</strong> <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;**Best Practices**&quot;">​</a></h2><ul><li><strong>Start with your materials.</strong> Because every mismatch is measured against your show notes and feed, accurate, complete metadata is the foundation. Make sure your host names, description, and topics reflect your show as it is today.</li><li><strong>Prioritize the clear errors.</strong> Wrong host names, confused shows, and made-up details do the most damage to listener trust — close those first.</li><li><strong>Re-check after you make changes.</strong> Knowledge Check is available to run once per week, so you can compare the available answers after making changes.</li><li><strong>Watch the Trained vs. Web search gap.</strong> Differences between answers can suggest where to investigate, but do not establish why an assistant gave an answer.</li></ul><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>Knowledge Check works alongside the rest of the AI Visibility tools to give you a complete picture of how AI sees your show:</p><ul><li><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> — tracks how often AI assistants recommend your podcast across topics</li><li><strong><a href="/features/ai-leaderboard.html">AI Leaderboard</a></strong> — shows which podcasts AI recommends most for any topic</li><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — optimizing your metadata for search also helps AI describe your show accurately</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>Knowledge Check is a paid feature. Free users see a preview of what the check covers along with an <strong>Upgrade to run a knowledge check</strong> prompt; upgrading unlocks the ability to run checks and view full results. Each podcast can run one check per week.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Run a check whenever you rebrand, change hosts, or shift your show&#39;s focus — these are exactly the moments AI is most likely to be out of date</li><li>Use the <strong>verify link</strong> on any card to confirm an assistant&#39;s answer yourself before deciding whether a fix is needed</li><li>Pair Knowledge Check with <a href="/features/ai-mentions.html">AI Mentions</a>: Mentions tells you whether AI recommends you, Knowledge Check tells you whether it describes you correctly</li></ul>',33)])])}const p=t(n,[["render",i]]);export{w as __pageData,p as default};
